    "id": "FS21677282-001",
    "platform": "马蜂窝（研究转录）",
    "date": "2019-06-06",
    "text": "中国工业博物馆坐落于沈阳市铁西区卫工北街14号，是在原沈阳铸造博物馆进行改造、扩建而成，其原址是沈阳铸造厂。博物馆由通史馆、机床馆、铸造馆、铁西馆、汽车馆等几个展馆主成。展馆展出多钟中外老式机床、上世纪30年代初的铁西规划图、新中国第一枚国徽、红旗汽车、林肯、奔驰等外国汽车。铁西区原是沈阳工业区，经历了日本殖民工业、国民党时期工业和新中国工业等几个不同的历史时期。这里曾经有人们熟知的第一机床厂、第二机床厂、第三机床厂、矿山机械厂、鼓风机厂、水泵厂等等。近些年，重工业厂区西迁，铁西区生态宜居环境迅速提高，2008年荣获全国唯一的联合国人居署“全球宜居城区示范奖”，2009年被评为“新中国建国60年60大地标”之一。做为老产业工人之子，也曾经在制造业工作过的我，特别喜欢这里的，虽然有些展馆里还夹扎着浓郁的机油味，但这恰恰是工业的真实写照。不过可惜的是，现在场馆正在改造，不少展馆没有开放。前些年跟着父母来过一次，展馆里还有一个大食堂，布局就像以前的工人大食堂，菜很便宜，当时午饭就在食堂吃的。展馆后面有一个休闲广场，停着几辆下线的无轨电车。但现在食堂已经不对外开放、休闲广场也暂不开放，二楼图书馆也暂不对外开放，非常可惜。",
