    "platform": "马蜂窝（研究转录）",
    "date": "2018-10-09",
    "text": "中国工业博物馆坐落于国家六大区域中心城市，东北第一大城市---沈阳。沈阳有着“共和国长子”和“东方鲁尔”的美誉，是中国乃至东北亚地区规模最大的工业中心城市。中国工业博物馆（一期）位于沈阳市铁西区卫工北街与北一西路交汇处，于2012年5月18日世界博物馆日开馆。现建有机床馆、铸造馆、通史馆、铁西新区十年馆。博物馆总占地面积8万平方米，建筑面积6万平方米。中国工业博物馆目前征集的文物来自上海、北京、内蒙古等20多个省区市及香港特别行政区，包括国家一级文物1件，国家二、三级文物10件。2008年6月辽宁省政府公布沈阳原铸造厂翻砂车间为辽宁省第八批省级文物保护单位。",
