    "id": "FS21677282-042",
    "platform": "马蜂窝（研究转录）",
    "date": "2014-07-12",
    "text": "中国铁道博物馆位于北京市朝阳区，在铁科院环行铁道附近。行车路线： 东四环北路路霄云桥向东，至大山子环岛向北，至大山子路口向东，穿过铁道后在路口向左，继续直行至下一道口，不穿过、左转，直行就到了。公交路线：坐403、813、629和小30在环行铁道下车，这里有一个铁路道口。不管是开车还是徒步，都得在铁路道口继续往西前行，来到一个丁字路口，这时你向左走，路会越来越窄，当你走到另一个铁路道口时，你会发现你的左边有一条小路，路的尽头是一座很大的蓝顶白色建筑，就是博物馆的机车陈列厅了。博物馆一共分三期工程，首期就是这个机车陈列厅，第二期是他们自己的办公楼，第三期是各种文献和小文物的陈列厅。博物馆每星期二至日开放，电话是010-64381317/1517。路电是41314/74。门票20元，离休、70岁以上老人、残疾人、学生、路内职工半价。",
    "source": "Figshare · 博物馆历史评论",
