    "text": "中国铁道博物馆是唯一的国家级专业铁路博物馆，它的前身是铁道部科学技术馆，1978年成立，2003年更名为中国铁道博物馆，主要任务是负责铁路文物、科研成果等展品的收藏、保管、陈列、展示及编辑研究工作。中国铁道博物馆有三个馆：正阳门馆、东郊馆、詹天佑纪念馆。",
