    "id": "FS21677282-086",
    "platform": "马蜂窝（研究转录）",
    "date": "2014-04-18",
    "text": "铁路博物馆有两个馆，一个是在酒仙桥附近，另一个在前门附近，是由老前门火车站改造而成的，老前门火车站的那个馆主要是介绍的中国铁路发展史，而实际的展览物并不是很多；想学历史的可以去前门的那个；而对火车有着浓厚的兴趣的，可以去酒仙桥的那个，那里有着很多实际展出的物品，包括很多机车及火车车厢，还有模拟列车驾驶的。如果对火车很感兴趣这两个馆都是值得一去的。",
