    "date": "2015-10-21",
    "text": "以前的正阳门火车站改造的，现在分为地上三层地下一层，主要是介绍中国火车的发展历史，展馆装修的很现代化，有诸多模型能更直观地了解与火车相关的一系列内容。美中不足的是由于场地所限很多没有交代清楚，供游人休息的地方少了一点，还需要在增加一些互动的设备，另外无障碍设施不是很完全。",
