    "text": "云南 铁路博物馆位于 昆明 市 北京 路913号，利用 昆明 火车北站的候车室改建而成，2004年开馆，主要展示 昆明 铁路发展历史，因其独特的历史和文化价值，现已被命名为全国青少年教育基地、全国铁路和 云南 省爱国主义教育基地以及 云南 省科普教育基地。票价10元/人。",
