    "text": "来这里，主要是为了溜娃，俩小男孩最喜欢火车且参与度强。博物馆就建在昆明北站，但是昆明北站的交通功能可能已经基本没有了，因为临近出在大修地铁，且全无火车站的繁忙景象。能免费寄存行李。在三层展馆的廊桥上，俯视一层的各类火车和车厢实物。",
