    "text": "滇越铁路是一段厚重的历史，个碧石这条民营铁路更是鲜为人知，在这里都可以近距离了解。展品也很有意思，宋美龄曾经乘坐的米其林专列实在是萌得超出想象。在这里还可以乘坐米轨小火车，只是开发的不太好，乘坐体验和沿途风景都不太好。",
