    "text": "铁道迷的天堂，在假铁道迷眼里同样是另一种不可错过的风景。不管是白色大派头米其林机车，红色邮政车绿色滇越客运车还是黄色的木质车厢，历史从眼前走过，被视觉和实感的双重冲击。然后坐着东方红穿过闹市，看到人群，遇见繁花。",
