    "text": "原来的昆明北站，也是滇越铁路的起始站，是个很有历史底蕴的铁路博物馆，建筑很漂亮，花十元钱就能进去读一段有关滇越铁路的历史。且博物馆内除了介绍历史外还有对云南铁路地位的展望跟西南一些铁路干线的介绍，还展有一些车头，火车迷可不能错过那。",
