    "text": "带孩子去过三次，都是去坐小火车，博物馆进去看过一次，很值得看，很有意义。但是儿子还是超级喜欢坐着火车慢慢转一圈，往返的车票，成人票2元，10点多上车，12点半返回上车点，很多爷爷奶奶带的孩子坐着玩。有时间可以去坐的玩，很不错。",
