    "text": "一段凝聚着中国铁路史的展馆，它和滇越铁路紧密的联系在一起，滇越铁路作为中国第一条申报世界遗产的铁路，那份沉甸甸的历史不用再说，光以目前国内极少还在运营的米轨铁路这一事实，就值得大家去展馆参观和了解。",
