    "text": "里面一共五层，建议从最上面开始逛，分为创造馆，进步馆和未来馆，里面有互动，有大人和小孩的驾驶体验是免费的，也有风力的那种实体体验是收费的，里面有志愿者，有一个公交上面的假人有点恐怖，孩子小有点怕，二层有快餐，价格也不算特贵，三四十，有卖模型车的，小朋友去看看挺好的",
